        if (knockBack) {
            collisionOn = false;
            gp.cChecker.checkTile(this);
            gp.cChecker.checkObject(this, true);
            gp.cChecker.checkEntity(this, gp.npc);
            gp.cChecker.checkEntity(this, gp.monster);

            if (collisionOn) {
                knockBackCounter = 0; knockBack = false; speed = defaultSpeed;
            } else {
                switch (knockBackDirection) {
                    case "up":    worldY -= speed; break;
                    case "down":  worldY += speed; break;
                    case "left":  worldX -= speed; break;
                    case "right": worldX += speed; break;
                }
            }
            knockBackCounter++;
            if (knockBackCounter == 10) { knockBackCounter = 0; knockBack = false; speed = defaultSpeed; }

        } else if (attacking) {
            attacking();

        } else if (keyH.spacePressed) {
            guarding = true;
            guardCounter++;

        } else if (keyH.upPressed || keyH.downPressed ||
                   keyH.leftPressed || keyH.rightPressed || keyH.enterPressed) {

            // Direction
            if      (keyH.upPressed)    direction = "up";
            else if (keyH.downPressed)  direction = "down";
            else if (keyH.leftPressed)  direction = "left";
            else if (keyH.rightPressed) direction = "right";

            // Collision
            collisionOn = false;
            gp.cChecker.checkTile(this);

            int objIndex     = gp.cChecker.checkObject(this, true);
            pickUpObject(objIndex);

            int npcIndex     = gp.cChecker.checkEntity(this, gp.npc);
            interactNPC(npcIndex);

            int monsterIndex = gp.cChecker.checkEntity(this, gp.monster);
            contactMonster(monsterIndex);

            gp.eHandler.checkEvent();

            if (!collisionOn && !keyH.enterPressed) {
                switch (direction) {
                    case "up":    worldY -= speed; break;
                    case "down":  worldY += speed; break;
                    case "left":  worldX -= speed; break;
                    case "right": worldX += speed; break;
                }
            }

            if (keyH.enterPressed && !attackCanceled) {
                // Quiz-based game: no physical attack, Enter is interact only
                attackCanceled = true;
            }

            attackCanceled    = false;
            keyH.enterPressed = false;
            guarding  = false;
            guardCounter = 0;

            spriteCounter++;
            if (spriteCounter > 12) {
                spriteNum     = (spriteNum == 1) ? 2 : 1;
                spriteCounter = 0;
            }

        } else {
            standCounter++;
            if (standCounter == 20) { spriteNum = 1; standCounter = 0; }
            guarding     = false;
            guardCounter = 0;
        }

