    public void pickUpObject(int i) {
        if (i == 999) return;
        Entity obj = gp.obj[gp.currentMap][i];
        if (obj == null) return;

        if (obj.type == type_pickupOnly) {
            obj.use(this);
            gp.obj[gp.currentMap][i] = null;
        } else if (obj.type == type_obstacle) {
            if (keyH.enterPressed) {
                attackCanceled = true;
                obj.interact();
            }
        } else {
            // Inventory item
            if (canObtainItem(obj)) {
                gp.playSE(1);
                gp.ui.addMessage("Got " + obj.name + "!");
            } else {
                gp.ui.addMessage("Cannot carry more!");
            }
            gp.obj[gp.currentMap][i] = null;
        }
    }

    public void interactNPC(int i) {
        if (i == 999) return;
        if (keyH.enterPressed) {
            attackCanceled = true;
            gp.npc[gp.currentMap][i].speak();
        }
        gp.npc[gp.currentMap][i].move(direction);
    }

    public void contactMonster(int i) {
        if (i == 999) return;
        if (!invincible && !gp.monster[gp.currentMap][i].dying) {
            // Only trigger battle when player PRESSES ENTER near enemy
            if (keyH.enterPressed) {
                // Must have at least 3 scrolls before battling monsters
                if (scrollsCompleted < 3) {
                    gp.ui.addMessage("Collect scrolls first! Need at least 3.");
                    keyH.enterPressed = false;
                    return;
                }
                invincible = true;
                invincibleCounter = 0;
                gp.currentEnemyIndex = i;
                // Boss gets full quiz (questions = HP), regular enemies get 3
                int numQ = gp.monster[gp.currentMap][i].boss ? gp.monster[gp.currentMap][i].life : 3;
                gp.quizManager.startBattleQuiz(numQ);
                gp.gameState = gp.quizState;
                keyH.enterPressed = false;
            }
        }
    }

    /** Check if all Memory Fragments are defeated and award KP */
    public void checkAllFragmentsDefeated() {
        // Count alive non-boss monsters (indices 0-4 are Memory Fragments)
        // A null or dying monster counts as defeated
        int aliveCount = 0;
        for (int i = 0; i < 5; i++) {
            if (gp.monster[0][i] != null && gp.monster[0][i].alive && !gp.monster[0][i].dying) {
                aliveCount++;
            }
        }
        if (aliveCount == 0 && knowledgePoints < 70) {
            int bonus = 70 - knowledgePoints;
            knowledgePoints = 70;
            gp.ui.showToast("All Memory Fragments defeated! KP maxed to 70! (+" + bonus + ")");
            gp.ui.addMessage("You now have enough knowledge to enter the castle.");
        }
    }

    public void damageMonster(int i, Entity attacker, int atk, int knockBackPower) {
        if (i == 999) return;
        Entity mon = gp.monster[gp.currentMap][i];
        if (mon == null || mon.invincible) return;

        gp.playSE(5);
        if (knockBackPower > 0) setKnockBack(mon, attacker, knockBackPower);
        if (mon.offBalance) atk *= 2;

        int damage = atk - mon.defense;
        if (damage <= 0) damage = 1;
        mon.life -= damage;
        gp.ui.addMessage(damage + " damage!");
        mon.invincible = true;
        mon.damageReaction();

        if (mon.life <= 0) {
            mon.dying = true;
            gp.ui.addMessage("Defeated " + mon.name + "!");
            gp.ui.addMessage("EXP +" + mon.exp);
            gainXP(mon.exp, "enemy defeated");
            enemiesDefeated++;
            checkBadgeConditions();
            checkAllFragmentsDefeated();
        }
    }

    public void checkLevelUp() {
        if (exp >= nextLevelExp) {
            level++;
            exp -= nextLevelExp;
            nextLevelExp += (level <= 4) ? 4 : 8;
            maxLife  += 2;
            life     = maxLife; // full heal on level up
            strength++;
            dexterity++;
            attack  = getAttack();
            defense = getDefense();
            gp.playSE(7);
            gp.ui.addMessage("LEVEL UP! Now level " + level + "!");
            gp.ui.levelUpFlashCounter = 15;  // White flash effect
        }
    }

    public boolean canObtainItem(Entity item) {
        if (inventory.size() < maxInventorySize) {
            inventory.add(item);
            return true;
        }
        return false;
    }

