    public void addKnowledgePoints(int kp) {
        knowledgePoints += kp;
        gp.ui.addMessage("+" + kp + " Knowledge Points!");
        gp.playSE(1);
        checkBadgeConditions();
    }

    public void unlockBadge(String badgeName) {
        for (Badge b : badges) {
            if (b.getBadgeName().equals(badgeName) && !b.isUnlocked()) {
                b.award();
                gp.ui.addMessage("Badge: " + badgeName + "!");
                gp.playSE(4);
            }
        }
    }

    public void checkBadgeConditions() {
        if (scrollsCompleted  >= 3)  unlockBadge("Knowledge Seeker");
        if (scrollsCompleted  >= 10) unlockBadge("Scroll Master");
        if (enemiesDefeated   >= 2)  unlockBadge("Memory Breaker");
        if (hasDefeatedShona)        unlockBadge("SDG Hero");
    }

    public String getBadgesAsText() {
        StringBuilder sb = new StringBuilder();
        for (Badge b : badges) {
            if (b.isUnlocked()) {
                if (sb.length() > 0) sb.append("|");
                sb.append(b.getBadgeName());
            }
        }
        return sb.length() > 0 ? sb.toString() : "None";
    }

